import{_ as t,C as r,o as d,c,E as s,a2 as n}from"./chunks/framework.BXyf8PVu.js";const S=JSON.parse('{"title":"Musico","description":"","frontmatter":{"pageClass":"project-case-study","title":"Musico","order":5},"headers":[],"relativePath":"zh/projects/musico.md","filePath":"zh/projects/musico.md"}'),i={name:"zh/projects/musico.md"};function a(g,o,l,u,h,p){const e=r("ProjectHero");return d(),c("div",null,[s(e,{index:"05",eyebrow:"软件工程 · 原生音频",title:"Musico：原生跨平台离线音乐播放器",summary:"一款面向 Apple、Android 与 Windows 的离线、文件夹优先、多队列本地音乐播放器——坚持零 Web 套壳，并内置统一的跨平台 JavaScript 扩展运行时。",year:"2025–2026",role:"架构设计、原生界面与音频工程",methods:"SwiftUI · Jetpack Compose · .NET 8 WPF · JavaScriptCore / QuickJS / Jint",chart:"/charts/musico-architecture.html?lang=zh","image-alt":"Musico 在 Apple、Android 与 Windows 原生客户端之间的交互式架构图",docs:"https://musico.seanpnex.win/?lang=zh",repo:"https://github.com/SEANPNEX/Musico"}),o[0]||(o[0]=n('<h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>如今绝大多数跨平台桌面与移动应用都依赖 Electron 或内嵌 WebView，为了单一前端界面层，往往牺牲了内存占用、原生音频管线以及系统级媒体集成。而对于拥有大量本地曲库的听众而言，流媒体应用常常忽略两件最核心的事：保留原本的文件夹层级，以及在多个独立播放队列之间自由切换而不丢进度。</p><p><strong>Musico</strong> 尝试了另一种工程路径：向 <strong>Musicolet</strong> 与 <strong>YRRLYB/Aria</strong> 致敬，为 Apple、Android 与 Windows 分别打造 <strong>100% 原生</strong> 的离线文件夹音乐播放器，同时在三端保持一致的曲库模型、播放语义与自定义音源扩展体系。</p><h2 id="三端原生客户端-零-web-套壳" tabindex="-1">三端原生客户端，零 Web 套壳 <a class="header-anchor" href="#三端原生客户端-零-web-套壳" aria-label="Permalink to &quot;三端原生客户端，零 Web 套壳&quot;">​</a></h2><p>每个平台都使用各自的原生 UI 框架、音频引擎与系统媒体控制接口，并各自内嵌轻量级 JavaScript 引擎来运行扩展：</p><table tabindex="0"><thead><tr><th>客户端</th><th>目标平台</th><th>技术栈</th><th>原生设计与系统集成</th></tr></thead><tbody><tr><td><code>Musico/</code></td><td>iOS 17+、iPadOS、macOS (Catalyst)</td><td>Swift、SwiftUI（<code>@Observable</code>）、<code>AVAudioEngine</code> + <code>AVAudioUnitEQ</code>、<code>MPNowPlayingInfoCenter</code>、<code>JavaScriptCore</code>（<code>Compression</code> + <code>CryptoKit</code>）</td><td>Apple HIG — iOS 采用标签页、弹窗与滑动操作（<code>allowsFullSwipe: false</code> 防止误删文件夹，并支持队列/播放列表左滑移除后 <strong>撤销（Undo）</strong>）；macOS 提供 <code>NSVisualEffectView</code> 毛玻璃半透明效果、独立侧边栏配色、<code>Cmd+K</code> 命令面板、悬浮迷你播放器与拖拽导入</td></tr><tr><td><code>MusicoAndroid/</code></td><td>Android 8.0+ (API 26+)</td><td>Kotlin、Jetpack Compose、AndroidX Media3（ExoPlayer + <code>MediaSessionService</code>）、SAF <code>DocumentFile</code>、<code>DynamicsProcessing</code> EQ、<code>QuickJS</code>（<code>quickjs-kt</code>）</td><td>Material 3 / Material You — 动态取色、自适应 <code>NavigationBar</code> / <code>NavigationRail</code>、<code>ModalBottomSheet</code>、Outlook × Material You 两段式 <code>MusicoSwipeActionRow</code> 滑动手势（干净裁剪的背景操作轨、触觉阻尼确认点、<code>DragReorder</code> 手柄防滑动锁定确保 <code>≡</code> 拖拽手柄永不卡顿）、无勾选图标拥挤的单行分段选择器、带队列 <strong>撤销（Undo）</strong> 的深色 <code>MusicoSnackbarHost</code> 提示条、自定义外观主题，以及从设备/<code>Musico</code> 文件夹删除</td></tr><tr><td><code>MusicoWindows/</code></td><td>Windows 10 (2004+) 与 Windows 11</td><td>C# / .NET 8 WPF、NAudio（<code>BiQuadFilter</code> 十段均衡器）、TagLibSharp、Windows 10 SMTC、<code>Jint</code></td><td>Fluent Design — Windows 11 DWM 圆角与窗口背景材质及亚克力（Acrylic）、独立侧边栏配色与不透明度、<code>Ctrl+K</code> 命令面板、悬浮迷你播放器与拖拽导入</td></tr></tbody></table><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>文件夹优先曲库、拖拽导入与安全删除：</strong> 挂载本地目录（如 <code>Music</code>、<code>Documents</code> 或自定义文件夹）并保留原始目录层级，也可在 macOS/Windows 上直接将本地文件夹和音频文件拖拽到窗口中（拖入文件夹会挂载至 <strong>文件夹</strong>，拖入音轨可立即播放并将曲库外文件复制到默认音乐文件夹）。当硬盘拔出或文件夹移动时，<strong>重新定位（Relocate）</strong> 可无损恢复链接而不丢失歌单或听歌记录。删除操作清晰区分 <strong>从音乐库移除（Remove from Library）</strong> 与磁盘删除（macOS 上的 <strong>移到废纸篓</strong>、Windows 上的 <strong>移至回收站</strong>、iOS/Android 上的 <strong>从设备删除</strong>，包含 Android 的 <code>Musico</code> 文件夹）。广泛支持无损与有损格式，涵盖 FLAC、ALAC、WAV、AIFF、MP3、AAC/M4A（视平台还支持 OGG、Opus、WMA 与 WebM）。</li><li><strong>云端文件夹、可选 Drive OAuth 2.0 与离线同步：</strong> 可在 <strong>文件夹（Folders）</strong> 中直接挂载公开或带 Cookie 鉴权的来源——覆盖 <strong>YouTube / YouTube Music</strong>（歌单、<code>RD</code> 混音、专辑、单曲）、<strong>Bilibili</strong>（<code>BV</code>/<code>av</code> 多 P 视频、收藏夹 <code>favlist</code>、合集）以及 <strong>Google Drive</strong>（递归子目录扫描与单文件）。公开/分享 Drive 链接保持免登录即用；如需访问私人文件夹或绕过大文件下载确认页，可在 <strong>设置 → Google Drive 账号</strong> 可选接入用户自己的免费桌面应用 OAuth 2.0 客户端 ID（<code>drive.readonly</code> + <code>userinfo.email</code>，Testing 模式，自动监听 <code>http://127.0.0.1:&lt;port&gt;/oauth2callback</code>，7 天 Testing 令牌过期后可通过 <strong>重新连接 Google Drive</strong> 刷新）。曲目可通过 <code>.musico-cloud.json</code> 清单保存到本地，并通过 <strong>从云端更新（Update from Cloud）</strong> 增量刷新。</li><li><strong>多独立播放队列、去重 <code>Play Next</code>（下一首播放）与移动端滑动手势：</strong> 根据不同心情或听歌场景开启多个并行队列，随时重命名、排序、清空或切换队列；每个队列独立记录当前曲目、播放进度、随机顺序与循环模式（<code>关闭</code> / <code>全部</code> / <code>单曲</code>）。三端（Apple、Android 与 Windows）统一支持 <strong>去重 <code>Play Next</code></strong>（<code>insertNext</code>），会将队列中已有的非当前播放条目干净地移动至下一首位置而非重复插入，同时不打断正在播放的歌曲。三端对齐的移动端滑动手势支持右滑 <strong>下一首播放（Play Next）</strong>；在 <strong>歌曲（Songs）</strong> 中左滑打开 <strong>从音乐库移除</strong> / <strong>从设备删除</strong> 确认弹窗（临时云端试听队列中禁用）；在 <strong>队列（Queues）</strong>、<strong>播放列表（Playlists）</strong> 与 <strong>收藏（Favourites）</strong> 中左滑立即移除并弹出 <strong>撤销（Undo）</strong> 提示，完整恢复队列顺序、当前曲目索引与播放断点时间戳；Android 端同时将文件夹左滑删除阈值提高至 <code>~44%</code>（最低 <code>140dp</code>）以防误删。</li><li><strong>统一外观设置与桌面端效率功能：</strong> 统一 <strong>设置</strong>（<code>Cmd+,</code> / <code>Ctrl+,</code>）提供跟随系统/浅色/深色模式、精选背景与强调色预设、自定义十六进制/RGB/系统取色器、实时 <strong>正在播放预览（Now Playing Preview）</strong>、内置 <strong>WCAG 2.1 对比度检测</strong> 与一键 <strong>自动修复对比度（Auto-fix Contrast）</strong>，以及可调节 <strong>图片可见度</strong>（不透明度）与 <strong>背景模糊</strong> 的自定义背景图片。桌面端还提供全局 <strong>命令面板 / 快速跳转</strong>（<code>Cmd+K</code> / <code>Ctrl+K</code>）、<strong>悬浮迷你播放器</strong> 窗口（<code>Cmd+Shift+N</code> / <code>Ctrl+Shift+N</code>）以及丰富的键盘快捷键（歌词 <code>Cmd+Shift+L</code> / <code>Ctrl+Shift+L</code> / <code>L</code>、队列 <code>Cmd+Shift+Q</code> / <code>Ctrl+Shift+Q</code> / <code>Q</code>、快进退 <code>±10s</code>、音量 <code>±5%</code>、静音、随机/循环、正在播放）。</li><li><strong>播放与曲库细节：</strong><ul><li><strong>10 段 ISO 均衡器</strong>（<code>31 Hz</code>–<code>16 kHz</code>），提供 <code>-12 dB</code> 至 <code>+12 dB</code> 前置增益、8 种预设及 <code>Custom</code> 自定义档。</li><li><strong>同步歌词与纯文本歌词：</strong> 按 <strong>手动导入</strong> → <strong>同目录同名</strong> <code>.lrc</code>/<code>.txt</code> → <strong>内嵌标签</strong> 顺序自动回退读取，支持多时间戳 <code>.lrc</code> 解析、UTF-8 / UTF-16 BOM / GB18030 编码识别、点击歌词跳转、自定义字号与对齐方式，以及 <strong>回到当前行（Sync to current line）</strong>。</li><li><strong>定时睡眠、听歌统计与标签编辑：</strong> 支持 <code>5</code>–<code>90</code> 分钟定时或 <strong>当前歌曲播完后停止</strong>，听歌统计（<strong>最近播放</strong>、<strong>最多播放</strong>、<strong>久未播放</strong>、<strong>从未播放</strong>，以及 <strong>最常听艺人</strong> 与 <strong>最常听专辑</strong>），行内元数据与封面编辑、系统媒体控制，以及 <code>English</code> / <code>简体中文</code> 实时切换。</li></ul></li></ul><h2 id="跨平台-javascript-扩展机制" tabindex="-1">跨平台 JavaScript 扩展机制 <a class="header-anchor" href="#跨平台-javascript-扩展机制" aria-label="Permalink to &quot;跨平台 JavaScript 扩展机制&quot;">​</a></h2><p>Musico 没有为了支持社区或个人音源而嵌入庞大的 WebView，而是让同一份 CommonJS 脚本（<code>.musico.js</code>）或 ZIP 压缩包（<code>.musicoext</code>）直接运行在三端各自内嵌的原生 JS 运行时中（Apple 使用 <strong>JavaScriptCore</strong>，Android 使用 <strong>QuickJS</strong>，Windows 使用 <strong>Jint</strong>）：</p><ul><li><strong>显式权限审查与隔离登录：</strong> 新导入的扩展默认保持停用状态，直到用户审查其声明的 <code>permissions.hosts</code> 域名白名单与能力字段（如 <code>&quot;cookie&quot;</code>、<code>&quot;qr_login&quot;</code>、<code>&quot;web_login&quot;</code>、<code>&quot;tree&quot;</code> 或 <code>&quot;proxy&quot;</code>）。<code>&quot;web_login&quot;</code> 能力配合条件必填的清单字段 <code>webLogin</code>（<code>{ loginUrl, cookieDomains, requiredCookies?, userAgent? }</code>），会严格仅用于登录 Cookie 捕获时打开隔离的临时系统 WebView（<strong>WKWebView</strong> / <strong>Android WebView</strong> / <strong>WebView2</strong>）——让播放器界面保持 100% 原生——同时支持脱敏 <code>cookies.txt</code> 文件导入。</li><li><strong>官方插件生态（<code>v2026.11.26</code>）：</strong> 官方插件以开箱即用的扩展包形式发布，覆盖 <strong>YouTube Search</strong> <code>v1.2.0</code>（<code>web_login</code> + 音质分级）、<strong>Bilibili Search</strong> <code>v1.2.0</code>（<code>qr_login</code> + Hi-Res/FLAC 档）、<strong>NetEase Cloud Music（网易云音乐）</strong> <code>v1.2.0</code>（9 档音质 + <code>qr_login</code>）以及 <strong>Apple Music</strong> <code>v1.0.1</code>（<code>searchLyrics</code> 透传 Bearer Token + 编码格式/封面回退）。</li><li><strong>可控操作与本地调试：</strong> 包含每个扩展独立的设置面板、200 条滚动日志查看器、不破坏既有曲库与缓存音频的安全停用/卸载流程，以及用于在本地验证扩展脚本的 Node.js 一致性测试工具（<code>docs/extensions/tools/mock-runner.mjs</code>）。</li></ul><h2 id="发行构建与更新工程" tabindex="-1">发行构建与更新工程 <a class="header-anchor" href="#发行构建与更新工程" aria-label="Permalink to &quot;发行构建与更新工程&quot;">​</a></h2><p>多平台 GitHub Actions 工作流为所有目标平台自动构建、测试并发布带 Tag 的版本（最新 <code>v1.3.4</code>）——产出 macOS Catalyst <code>.dmg</code>、iOS 未签名 <code>.ipa</code>、Android release/debug <code>.apk</code>，以及 Windows NSIS 安装包（<code>Setup.exe</code>）与自包含绿色便携版 <code>.zip</code>（存在 <code>portable.txt</code> 时将数据保存在 <code>.\\Data\\</code>）。Windows、Android 与 macOS 均内置应用内更新器，支持检查 <code>releases/latest</code>、校验 <code>SHA256SUMS.txt</code> 与 <strong>跳过此版本</strong>。</p><h2 id="仓库与下载" tabindex="-1">仓库与下载 <a class="header-anchor" href="#仓库与下载" aria-label="Permalink to &quot;仓库与下载&quot;">​</a></h2><ul><li><strong>文档与扩展中心：</strong> <a href="https://musico.seanpnex.win/?lang=zh" target="_blank" rel="noreferrer">musico.seanpnex.win/?lang=zh</a>（使用指南、官方插件与扩展 API v1 文档）</li><li><strong>源码仓库：</strong> <a href="https://github.com/SEANPNEX/Musico" target="_blank" rel="noreferrer">github.com/SEANPNEX/Musico</a>（MIT License）</li><li><strong>版本下载：</strong> <a href="https://github.com/SEANPNEX/Musico/releases/latest" target="_blank" rel="noreferrer">最新桌面与移动端发行版</a></li><li><strong>扩展开发文档：</strong> <a href="https://musico.seanpnex.win/developers/?lang=zh" target="_blank" rel="noreferrer">musico.seanpnex.win/developers/?lang=zh</a> · <a href="https://github.com/SEANPNEX/Musico/blob/main/docs/extensions/README.zh-CN.md" target="_blank" rel="noreferrer">GitHub 中文扩展指南</a></li></ul>',15))])}const b=t(i,[["render",a]]);export{S as __pageData,b as default};
